Looking at this problem: transform coordinates to u = x+y, v = x−y, which turns Manhattan distance into Chebyshev (L∞) distance. Then a set has max intra-distance ≤ D iff it fits in an axis-aligned square of side D. So we must decide whether all points can be covered by **two** squares of side D. Binary search D; normalize one square to u ∈ [umin, umin+D] with some v-window [c, c+D] (integer c suffices); the rest R(c) = {u>U} ∪ {v<c} ∪ {v>c+D} must fit in one square. Sweep c over event candidates (v, v+1, v−D, v−D−1) with prefix/suffix min-max of u over the v-sorted order — O(N) per check. Verified against the sample (answer 8) and several hand-constructed cases.

```c
#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

#define MAXN 300005
#define PINF  1152921504606846976LL
#define NINF  (-1152921504606846976LL)
#define VOFF  500000001LL

static int n;
static ll uu[MAXN], vv[MAXN];
static ll sv[MAXN], su[MAXN];
static ll pminU[MAXN + 2], pmaxU[MAXN + 2];
static ll sminU[MAXN + 2], smaxU[MAXN + 2];
static ll C1[2 * MAXN], C2[2 * MAXN];
static ll gUmin;

static char *ibuf = NULL;
static size_t ilen = 0, ipos = 0;

static void readAll(void){
    size_t cap = 1u << 20, len = 0, r;
    ibuf = (char *)malloc(cap);
    for (;;){
        r = fread(ibuf + len, 1, cap - len, stdin);
        len += r;
        if (r == 0) break;
        if (len == cap){ cap <<= 1; ibuf = (char *)realloc(ibuf, cap); }
    }
    if (len == cap){ cap += 8; ibuf = (char *)realloc(ibuf, cap); }
    ibuf[len] = '\0'; ilen = len; ipos = 0;
}

static inline ll nextInt(void){
    while (ipos < ilen && (ibuf[ipos] < '0' || ibuf[ipos] > '9')) ++ipos;
    ll x = 0;
    while (ipos < ilen && ibuf[ipos] >= '0' && ibuf[ipos] <= '9')
        x = x * 10 + (ll)(ibuf[ipos++] - '0');
    return x;
}

static int cmpLL(const void *a, const void *b){
    ll x = *(const ll *)a, y = *(const ll *)b;
    return (x < y) ? -1 : ((x > y) ? 1 : 0);
}

static int check(ll D){
    const ll U = gUmin + D;
    ll gMaxU = NINF, gMinU = PINF, gMaxV = NINF, gMinV = PINF;
    int gCnt = 0;
    for (int i = 0; i < n; ++i){
        if (uu[i] > U){
            ++gCnt;
            if (uu[i] > gMaxU) gMaxU = uu[i];
            if (uu[i] < gMinU) gMinU = uu[i];
            if (vv[i] > gMaxV) gMaxV = vv[i];
            if (vv[i] < gMinV) gMinV = vv[i];
        }
    }
    if (gCnt > 0 && (gMaxU - gMinU > D || gMaxV - gMinV > D)) return 0;

    const int TOT = 2 * n;
    {
        int i = 0, j = 0, k = 0;
        while (k < TOT){
            ll a = (i < n) ? sv[i] : PINF;
            ll b = (j < n) ? sv[j] + 1 : PINF;
            if (a <= b) C1[k++] = a, ++i; else C1[k++] = b, ++j;
        }
        i = 0; j = 0; k = 0;
        while (k < TOT){
            ll a = (i < n) ? sv[i] - D - 1 : PINF;
            ll b = (j < n) ? sv[j] - D : PINF;
            if (a <= b) C2[k++] = a, ++i; else C2[k++] = b, ++j;
        }
    }
    int idxL = 0, idxH = 0, p1 = 0, p2 = 0;
    ll lastC = 0; int hasLast = 0;
    while (p1 < TOT || p2 < TOT){
        ll c;
        if (p1 < TOT && (p2 >= TOT || C1[p1] <= C2[p2])) c = C1[p1++];
        else c = C2[p2++];
        if (hasLast && c == lastC) continue;
        lastC = c; hasLast = 1;

        while (idxL < n && sv[idxL] < c) ++idxL;
        while (idxH < n && sv[idxH] <= c + D) ++idxH;

        if (gCnt == 0 && idxL == 0 && idxH == n) return 1;

        ll rMaxU = gMaxU, rMinU = gMinU;
        if (pmaxU[idxL] > rMaxU) rMaxU = pmaxU[idxL];
        if (smaxU[idxH] > rMaxU) rMaxU = smaxU[idxH];
        if (pminU[idxL] < rMinU) rMinU = pminU[idxL];
        if (sminU[idxH] < rMinU) rMinU = sminU[idxH];
        if (rMaxU - rMinU > D) continue;

        ll rMaxV = gMaxV, rMinV = gMinV;
        if (idxL > 0){
            if (sv[idxL - 1] > rMaxV) rMaxV = sv[idxL - 1];
            if (sv[0] < rMinV) rMinV = sv[0];
        }
        if (idxH < n){
            if (sv[n - 1] > rMaxV) rMaxV = sv[n - 1];
            if (sv[idxH] < rMinV) rMinV = sv[idxH];
        }
        if (rMaxV - rMinV <= D) return 1;
    }
    return 0;
}

int main(void){
    readAll();
    n = (int)nextInt();
    for (int i = 0; i < n; ++i) uu[i] = nextInt();
    for (int i = 0; i < n; ++i) vv[i] = nextInt();
    for (int i = 0; i < n; ++i){
        ll a = uu[i], b = vv[i];
        uu[i] = a + b;   /* u = x + y */
        vv[i] = a - b;   /* v = x - y */
    }
    gUmin = PINF;
    ll gUmax = NINF;
    for (int i = 0; i < n; ++i){
        if (uu[i] < gUmin) gUmin = uu[i];
        if (uu[i] > gUmax) gUmax = uu[i];
    }
    const ll urange = gUmax - gUmin;

    static ll pak[MAXN];
    for (int i = 0; i < n; ++i)
        pak[i] = ((vv[i] + VOFF) << 31) | uu[i];
    qsort(pak, (size_t)n, sizeof(ll), cmpLL);
    for (int i = 0; i < n; ++i){
        su[i] = pak[i] & (((ll)1 << 31) - 1);
        sv[i] = (pak[i] >> 31) - VOFF;
    }

    pmaxU[0] = NINF; pminU[0] = PINF;
    for (int i = 1; i <= n; ++i){
        ll t = su[i - 1];
        pmaxU[i] = pmaxU[i - 1] > t ? pmaxU[i - 1] : t;
        pminU[i] = pminU[i - 1] < t ? pminU[i - 1] : t;
    }
    smaxU[n] = NINF; sminU[n] = PINF;
    for (int i = n - 1; i >= 0; --i){
        ll t = su[i];
        smaxU[i] = smaxU[i + 1] > t ? smaxU[i + 1] : t;
        sminU[i] = sminU[i + 1] < t ? sminU[i + 1] : t;
    }

    const ll vrange = sv[n - 1] - sv[0];
    ll lo = 0, hi = urange > vrange ? urange : vrange;
    while (lo < hi){
        ll mid = lo + ((hi - lo) >> 1);
        if (check(mid)) hi = mid; else lo = mid + 1;
    }
    printf("%lld\n", lo);
    return 0;
}
